import {Link} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'

export function FeatureBanner({type}: {type: 'reload' | 'error' | undefined}) {
  if (!type) {
    return null
  }

  const variant = type === 'reload' ? 'success' : 'critical'
  const bannerText =
    type === 'reload' ? (
      <span>
        Changes saved! Please{' '}
        <Link
          inline
          href="#"
          onClick={(e: React.MouseEvent<HTMLAnchorElement>) => {
            e.preventDefault()
            window.location.reload()
          }}
        >
          reload
        </Link>{' '}
        the page to view the changes.
      </span>
    ) : (
      <span>Unable to save changes. Please try again.</span>
    )

  return (
    <InlineMessage variant={variant} size="small">
      {bannerText}
    </InlineMessage>
  )
}
